  function finalizeMessage(el, fallbackText) {
    var cursor=el.querySelector('.cursor'); if(cursor) cursor.remove();
    var text = el._rawBuf||'';
    text=text.replace(/<tool_call>[\s\S]*?<\/tool_call>/g,'');
    text=text.replace(/<plan>[\s\S]*?<\/plan>/g,'');
    text=text.replace(/<think>[\s\S]*?<\/think>/g,'');
    var pi=text.indexOf('<tool_call>'); if(pi!==-1) text=text.substring(0,pi);
    var pp=text.indexOf('<plan>'); if(pp!==-1) text=text.substring(0,pp);
    var pt=text.indexOf('<think>'); if(pt!==-1) text=text.substring(0,pt);
    var inlineMedia=takeMediaDeclarations(text);
    text=inlineMedia.text.trim();
    var medias=pendingMedia.concat(inlineMedia.items); pendingMedia=[];
    if(!text && fallbackText) {
      var fallbackMedia=takeMediaDeclarations(fallbackText);
      text=fallbackMedia.text;
      medias=medias.concat(fallbackMedia.items);
    }
    if(!text && !medias.length) return;
    if(text && typeof marked!=='undefined') {
      marked.setOptions({breaks:true,gfm:true,highlight:function(code,lang){
        if(typeof hljs!=='undefined'&&lang&&hljs.getLanguage(lang)){try{return hljs.highlight(code,{language:lang}).value;}catch(e){}}
        if(typeof hljs!=='undefined'){try{return hljs.highlightAuto(code).value;}catch(e){}}
        return code;
      }});
      el.innerHTML = marked.parse(text);
      el.classList.add('rendered');
      if(window.lrEnhanceCode) window.lrEnhanceCode(el);
    }
    if(text) linkifyUrls(el);
    appendMediaGallery(el,medias);
    var actions = document.createElement('div'); actions.className='msg-actions';
    var ttsBtn = document.createElement('button'); ttsBtn.className='msg-action-btn'; ttsBtn.innerHTML='<svg width="1.2em" height="1.2em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"></polygon><path d="M15.54 8.46a5 5 0 0 1 0 7.07"></path><path d="M19.07 4.93a10 10 0 0 1 0 14.14"></path></svg> '+LaRuche.i18n.t('chat.lire');
    ttsBtn.onclick=function(){LaRuche.Voice.speakText(text,ttsBtn);}; actions.appendChild(ttsBtn);
    var copyBtn2 = document.createElement('button'); copyBtn2.className='msg-action-btn'; copyBtn2.innerHTML='<svg width="1.2em" height="1.2em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg> '+LaRuche.i18n.t('chat.copier');
    copyBtn2.onclick=function(){navigator.clipboard.writeText(text).then(function(){copyBtn2.classList.add('copied');copyBtn2.innerHTML='<svg width="1.2em" height="1.2em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><polyline points="20 6 9 17 4 12"></polyline></svg> '+LaRuche.i18n.t('chat.copie');setTimeout(function(){copyBtn2.classList.remove('copied');copyBtn2.innerHTML='<svg width="1.2em" height="1.2em" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="vertical-align: middle;"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"></path><rect x="8" y="2" width="8" height="4" rx="1" ry="1"></rect></svg> '+LaRuche.i18n.t('chat.copier');},2000);});}; actions.appendChild(copyBtn2);
    el.appendChild(actions);
    // Enrich timestamp with model + tokens on hover
    var row = el.closest('.message-row');
    if(row) {
      var tsEl = row.querySelector('.msg-timestamp');
      if(tsEl) {
        var modelName = LaRuche.Header.getModel() || '?';
        var tokens = Math.round(text.length / 4); // rough estimate
        var baseTime = tsEl.dataset.time || tsEl.textContent;
        tsEl.textContent = baseTime + '  ·  ' + modelName + '  ·  ~' + tokens + ' tokens';
      }
    }
    scrollToBottom();
    if(LaRuche.Voice.isAutoTts()) LaRuche.Voice.finishStream(text,ttsBtn);
  }

  // Auto-scroll "stuck to bottom": we only re-scroll IF the user was already at the bottom.
  // As soon as they scroll up to read, we stop bringing them back (until they scroll down themselves).
  // `force=true` for explicit actions (the user sends a message).
  var _chatStick = true, _chatScrollBound = false;
  function _bindChatScroll(){
    if(_chatScrollBound) return;
    var c=document.getElementById('chatContainer'); if(!c) return;
    c.addEventListener('scroll', function(){
      _chatStick = (c.scrollHeight - c.scrollTop - c.clientHeight) < 120;
    });
    _chatScrollBound = true;
  }
  function scrollToBottom(force) {
    _bindChatScroll();
    if(force) _chatStick = true;
    if(!_chatStick) return;
    requestAnimationFrame(function(){ var c=document.getElementById('chatContainer'); if(c) c.scrollTop=c.scrollHeight; });
  }

  // \u2500\u2500 Agentic feed: collapsible step timeline \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  var _feedStepN=0, _feedBody=null, _feedPrevCard=null, _feedLiveStartedAt=0, _feedTurnTitle='';
